const data = $input.first().json.body || $input.first().json;

// Solo mensajes outgoing (type 1 o string 'outgoing'), no privados
const isOutgoing = data.message_type === 1 || data.message_type === 'outgoing';
if (!isOutgoing) {
  return { forward: false, reason: 'not_outgoing', type: data.message_type };
}
if (data.private === true) {
  return { forward: false, reason: 'private' };
}

// Ignorar mensajes espejados por n8n IA (ya fueron enviados a ML directamente)
if (data.content_attributes?.source === 'n8n_ai') {
  return { forward: false, reason: 'ai_mirror' };
}

const conv = data.conversation;
if (!conv) {
  return { forward: false, reason: 'no_conversation' };
}

const attrs = conv.additional_attributes || {};
if (attrs.type !== 'post-venta') {
  return { forward: false, reason: 'not_postsale', attrs_type: attrs.type };
}

// pack_id: desde additional_attributes o meta.source_id
const packId  = String(attrs.pack_id || conv.meta?.source_id || '');
// buyer_user_id: identifier del contacto del contacto almacenado al crear la conversación
const buyerId = String(conv.meta?.sender?.identifier || '');
const accountId = data.account?.id;
const text    = (data.content || '').trim();

if (!packId || !buyerId || !text) {
  return { forward: false, reason: 'missing_data', packId, buyerId, hasText: !!text };
}

return {
  forward:        true,
  pack_id:        packId,
  buyer_user_id:  buyerId,
  account_id:     accountId,
  text
};

const __ra_helpers = this.helpers;
const __ra_toBuf = (b) => {
  if (Buffer.isBuffer(b)) return b;
  if (b && typeof b === 'object' && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data);
  if (typeof b === 'string') return Buffer.from(b);
  if (b && typeof b === 'object') return Buffer.from(JSON.stringify(b));
  return Buffer.from(String(b));
};
const __ra_toText = (b) => __ra_toBuf(b).toString('utf8');
const fetch = (url, opts = {}) => (async () => {
  try {
    const res = await __ra_helpers.httpRequest({
      method: (opts.method || 'GET').toUpperCase(),
      url,
      headers: opts.headers || {},
      body: opts.body,
      json: false,
      encoding: 'arraybuffer',
      returnFullResponse: true
    });
    return {
      ok: res.statusCode >= 200 && res.statusCode < 300,
      status: res.statusCode,
      json: async () => { const t = __ra_toText(res.body); try { return JSON.parse(t); } catch (e) { return t; } },
      text: async () => __ra_toText(res.body),
      arrayBuffer: async () => __ra_toBuf(res.body)
    };
  } catch (e) {
    return { ok: false, status: e.status || e.statusCode || 0, json: async () => ({}), text: async () => String(e.message || ''), arrayBuffer: async () => Buffer.alloc(0) };
  }
})();



const account = $('get_ml_credentials').first().json;
const data = $('filter_and_extract').first().json;
const text = data.text || '';
const isBridge = account.status === 'bridge' && account.bridge_enabled === true;
if ($env.REPLY_RECEIVE_ONLY === 'true' && account.receive_only === 'true') return { receive_only: true, text: text, skipped: true };
if (isBridge) {
  if (!$env.BRIDGE_SECRET || !$env.YOBOT_BRIDGE_URL) throw new Error('Bridge: BRIDGE_SECRET/YOBOT_BRIDGE_URL no configurados en n8n');
  const body = JSON.stringify({ ml_user_id: String(account.ml_user_id), pack_id: data.pack_id, text: text });
  const signature = (await (await fetch('http://rails:3000/bridge/sign', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': $env.BRIDGE_SECRET },
  body: JSON.stringify({ body })
})).json()).signature;
  const res = await fetch($env.YOBOT_BRIDGE_URL + '/api/bridge/send-message', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + $env.BRIDGE_SECRET, 'X-Bridge-Signature': signature }, body: body });
  if (!res.ok) throw new Error('Bridge send-message: ' + res.status);
  const sent = await res.json();
  await markDelivered(sent);
  return sent;
}
const res = await fetch('https://api.mercadolibre.com/messages/packs/' + data.pack_id + '/sellers/' + account.ml_user_id + '?tag=post_sale', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + (data.access_token || account.access_token) }, body: JSON.stringify({ from: { user_id: String(account.ml_user_id) }, to: { user_id: data.buyer_user_id }, text: text }) });
if (!res.ok) throw new Error('ML send: ' + res.status);
const sent = await res.json();
await markDelivered(sent);
return sent;

// Tras un envio exitoso: burbuja a delivered (doble check gris) + persiste ml_message_id de ML
// (content_attributes) para el sync de lectura (read, doble check azul). Best-effort.
async function markDelivered(sent) {
  const cwMessageId = $('chatwoot_webhook').item.json.body.id;
  const mlMessageId = String(sent.message_id || sent.id || '');
  if (!cwMessageId || !mlMessageId) return;
  try {
    await fetch('http://rails:3000/api/bridge/message-status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-internal-secret': 'reply_ai_internal_2026' },
      body: JSON.stringify({ account_id: data.account_id, message_id: cwMessageId, status: 'delivered', ml_message_id: mlMessageId })
    });
  } catch (e) {}
}
